def bbox(cells):
    rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
    return (max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)

def transform(grid):
    bycolor={}
    for v,cells in shapes(grid): bycolor.setdefault(v,[]).append(cells)
    cols=sorted(bycolor, key=lambda v: min(c[1] for cs in bycolor[v] for c in cs))
